const main=document.querySelector('#main'), actions=document.querySelector('#header-actions'), toast=document.querySelector('#toast');
const side=selector=>main.querySelector(':scope > .workspace > aside')?.querySelector(selector);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flash=s=>{toast.textContent=s;toast.classList.add('show');clearTimeout(flash.timer);flash.timer=setTimeout(()=>toast.classList.remove('show'),3000)};
const isLocalHost=['127.0.0.1','localhost','::1','[::1]'].includes(location.hostname);
if(location.pathname==='/'&&new URLSearchParams(location.hash.slice(1)).has('owner'))history.replaceState(null,'',location.pathname+location.search);
// A restored homepage may contain stale permissions and lists from a previous server version.
// Refresh only the homepage; review pages can contain unsent drafts.
window.addEventListener('pageshow',event=>{if(event.persisted&&location.pathname==='/')location.reload()});
const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
let review, pending=null, pendingThumb='', replying=null, submitting=false, commentAttempt=null, restoringDraft=false, commentVersion=0, trackedText=null;
const deletingComments=new Set();
window.addEventListener('beforeunload',e=>{saveDraft();if(!submitting&&!side('#body')?.value.trim())return;e.preventDefault();e.returnValue=''});
window.addEventListener('pagehide',saveDraft);
function draftKey(){return review?.id?'lanreview-draft:'+review.id:null}
function saveDraft(){if(restoringDraft)return;let key=draftKey(),body=side('#body');if(!key||!body)return;try{if(!body.value.trim()){sessionStorage.removeItem(key);return}sessionStorage.setItem(key,JSON.stringify({body:body.value,author:side('#author')?.value||'',anchor:pending,thumbnail:pendingThumb,parent_id:replying,attempt:commentAttempt}))}catch{let status=side('#draft-status');if(status)status.textContent='浏览器无法暂存草稿，离开页面会丢失。'}}
function removeDraft(){let key=draftKey();if(key)try{sessionStorage.removeItem(key)}catch{}}
async function api(url,options={}){let r;try{r=await fetch(url,options)}catch{throw Error(options.method==='POST'?(url.endsWith('/comments')?'连接中断，结果可能已保存；保持内容不变并重试，可避免重复。':'连接中断，结果可能已保存；请先刷新列表确认后再试。'):'无法连接服务，请检查网络后重试')} if(!r.ok){let d;try{d=await r.json()}catch{}let error=Error(d?.error||`请求失败（${r.status}）`);error.status=r.status;throw error}return r.json()}
function date(s){let d=new Date(s);return isNaN(d)?'':d.toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}
async function copy(url){try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(url);flash('链接已复制')}catch{showSharePanel(url)}}
function showSharePanel(url){let zone=main.querySelector('.document-zone');if(!zone)return;let panel=zone.querySelector('#share-panel');if(!panel){panel=document.createElement('div');panel.id='share-panel';panel.className='notice share-panel';panel.innerHTML='<label for="share-address">分享链接</label><div class="share-controls"><input id="share-address" readonly><button type="button" class="button secondary" data-copy>复制</button><button type="button" class="button secondary" data-close aria-label="关闭分享">关闭</button></div><p role="status">选中链接后按 Ctrl+C 复制。</p>';zone.insertBefore(panel,zone.querySelector('#content'));panel.querySelector('[data-close]').onclick=()=>panel.remove();panel.querySelector('[data-copy]').onclick=async()=>{let input=panel.querySelector('input'),status=panel.querySelector('[role=status]');input.focus();input.select();try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(input.value);status.textContent='链接已复制';return}if(document.execCommand('copy')){status.textContent='链接已复制';return}}catch{}status.textContent='未能自动复制，请按 Ctrl+C 复制选中的链接。'}}let input=panel.querySelector('input');input.value=url;input.focus();input.select();panel.scrollIntoView({behavior:motion(),block:'nearest'})}
function shareReview(){if(review.share_scope!=='lan'){let zone=main.querySelector('.document-zone');if(!zone)return;let notice=zone.querySelector('#share-local-notice');if(!notice){notice=document.createElement('div');notice.id='share-local-notice';notice.className='notice share-local-notice';notice.setAttribute('role','status');notice.innerHTML='<span>当前服务仅供本机访问，其他电脑无法打开链接。请以局域网模式启动服务后再分享。</span><button type="button" aria-label="关闭提示">关闭</button>';zone.insertBefore(notice,zone.querySelector('#content'));notice.querySelector('button').onclick=()=>notice.remove()}notice.scrollIntoView({behavior:motion(),block:'nearest'});return}copy(new URL(review.url,location.origin).href)}
function formatMediaTime(t){let total=Math.round(t*1000),minutes=Math.floor(total/60000),whole=Math.floor(total/1000)%60,fraction=total%1000;return `${minutes}:${String(whole).padStart(2,'0')}${fraction?'.'+String(fraction).padStart(3,'0').replace(/0+$/,''):''}`}
function label(a){if(!a)return '全文评论';if(a.type==='text')return `“${a.quote}”`;if(a.type==='image')return ['rect','polygon'].includes(a.region?.type)?'图片区域':'图片位置';if(a.type==='video')return `视频 ${formatMediaTime(a.time)}${Number.isFinite(a.end_time)?'–'+formatMediaTime(a.end_time):''}${a.region?(['rect','polygon'].includes(a.region.type)?' · '+(Number.isFinite(a.end_time)?'起始帧区域':'画面区域'):' · '+(Number.isFinite(a.end_time)?'起始帧位置':'画面位置')):''}`;return '评论'}
function selected(a,options={}){if(!a&&pending&&side('#body')?.value.trim()&&!confirm('清除定位后，这条草稿将作为全文评论发表。确定清除定位吗？'))return false;if(a)openDiscussion();if(submitting){flash('评论正在发表，请稍候');return false}if(a&&!options.adjust&&side('#body')?.value.trim()&&(replying||!pending||JSON.stringify(pending)!==JSON.stringify(a))){flash('当前评论草稿已保留；清空草稿后可重新选择位置');return false}if(a&&replying){clearReply();flash('已切换为定位评论')}clearTextAffordance();pending=a;if(!restoringDraft&&!options.keepThumb)pendingThumb=a&&(a.type==='image'||a.type==='video')?captureMediaThumbnail():'';clearVisual('draft');const el=side('#selected');if(el)el.innerHTML=a?`<div class="selected"><button type="button" id="clear-anchor">清除</button>定位到：${esc(label(a).slice(0,140))}${thumbnailMarkup(a)}</div>`:'';side('#clear-anchor')?.addEventListener('click',()=>selected(null));if(a){let panel=main.querySelector('.sidebar');if(panel)panel.scrollTop=panel.scrollHeight}saveDraft();return true}
function openDiscussion(){let w=main.querySelector('.workspace'),panel=side('#discussion')||main.querySelector('.sidebar'),toggle=document.querySelector('#discussion-toggle');if(!w||!panel)return;w.classList.remove('discussion-closed');panel.hidden=false;if(toggle){toggle.setAttribute('aria-expanded','true');toggle.textContent='收起讨论'}main.querySelector('#mobile-discussion-toggle')?.setAttribute('aria-expanded','true')}
function toggleDiscussion(){let w=main.querySelector('.workspace'),panel=main.querySelector('.sidebar'),toggle=document.querySelector('#discussion-toggle');if(!w||!panel)return;let close=!panel.hidden;panel.hidden=close;w.classList.toggle('discussion-closed',close);toggle.setAttribute('aria-expanded',String(!close));toggle.textContent=close?'展开讨论':'收起讨论';main.querySelector('#mobile-discussion-toggle')?.setAttribute('aria-expanded',String(!close))}
function prepareSelection(a){if(!a?.quote||submitting)return false;let text=side('#body');openDiscussion();if(text?.value.trim()&&(replying||!pending||JSON.stringify(pending)!==JSON.stringify(a))){flash('当前评论草稿已保留；清空草稿后可重新选择位置');return false}if(!selected(a))return false;let panel=main.querySelector('.sidebar');if(panel)panel.scrollTop=panel.scrollHeight;return true}
function clearTextAffordance(){trackedText=null;document.querySelector('#selection-affordance')?.remove()}
function showTextAffordance(anchor,rects,selectionId=null,frame=null,range=null){if(pending!==anchor)return;clearTextAffordance();trackedText={anchor,rects,selectionId,frame,range};let button=document.createElement('button');button.id='selection-affordance';button.type='button';button.className='selection-affordance';button.setAttribute('aria-label','前往所选内容的评论');button.title='前往评论';button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 5h16v11H9l-5 4V5z"/><path d="M8 9h8M8 12h5"/></svg>';button.addEventListener('pointerdown',e=>e.preventDefault());button.onclick=()=>{openDiscussion();let panel=main.querySelector('.sidebar'),input=side('#body');if(panel&&input){panel.scrollTop=panel.scrollHeight;input.focus({preventScroll:true})}};document.body.append(button);updateTextAffordance(false)}
function updateTextAffordance(cancelWhenHidden){let t=trackedText,button=document.querySelector('#selection-affordance');if(!t||!button||pending!==t.anchor){clearTextAffordance();return}let rects;try{rects=t.rects()}catch{rects=[]}let visible=Array.from(rects||[]).filter(r=>r.width>0&&r.height>0&&r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth);if(!visible.length){button.hidden=true;if(cancelWhenHidden&&pending===t.anchor&&!submitting&&!replying&&!side('#body')?.value.trim()){dismissTrackedTextOnScroll(t)}return}let r=visible[visible.length-1];button.hidden=false;button.style.left=Math.max(4,Math.min(innerWidth-38,r.right+4))+'px';button.style.top=Math.max(4,Math.min(innerHeight-38,r.bottom+4))+'px'}
function dismissTrackedTextOnScroll(t){if(!t||pending!==t.anchor||!dismissTemporaryAnchor())return;if(t.frame&&t.selectionId!=null){t.frame.contentWindow?.postMessage({type:'lanreview:clear-selection',selectionId:t.selectionId},'*')}else if(t.range){let selection=getSelection();if(selection?.rangeCount){let r=selection.getRangeAt(0),old=t.range;if(r.startContainer===old.startContainer&&r.startOffset===old.startOffset&&r.endContainer===old.endContainer&&r.endOffset===old.endOffset)selection.removeAllRanges()}}flash('已取消选区')}
let selectionScrollFrame=0;window.addEventListener('scroll',()=>{if(!trackedText)return;cancelAnimationFrame(selectionScrollFrame);selectionScrollFrame=requestAnimationFrame(()=>updateTextAffordance(true))},{passive:true});window.addEventListener('resize',()=>{if(trackedText)updateTextAffordance(false)});
function dismissTemporaryAnchor(){if(!pending||submitting||replying||side('#body')?.value.trim())return false;selected(null);return true}
function viewCommentAnchor(a){if(!a)return;if(pending){if(!side('#body')?.value.trim()&&!submitting&&!replying)dismissTemporaryAnchor();else{let current=side('#selected .selected');if(current){let note=current.querySelector('.viewing-notice');if(!note){note=document.createElement('div');note.className='viewing-notice';note.setAttribute('role','status');current.append(note)}note.textContent='正在查看已有评论；草稿仍针对上方位置。'}}}locate(a)}
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&dismissTemporaryAnchor()){if(window.CSS?.highlights)CSS.highlights.delete('review-anchor');getSelection()?.removeAllRanges()}});

async function home(){
  actions.innerHTML='';
  const fileTypes='.md,.markdown,.html,.htm,.png,.jpg,.jpeg,.webp,.gif,.avif,.mp4,.m4v,.webm,.mov';
  const uploadForm=`<form id="upload-file" class="upload-form"><label class="file-label" for="file">选择文件</label><input id="file" type="file" required accept="${fileTypes}"><button class="button" type="submit">创建评审</button><p class="hint">Markdown 引用的本地图片不会随单文件上传；请检查预览。交互 HTML 请仅使用可信文件。</p><p id="upload-error" class="import-error" role="alert"></p></form>`;
  const folderImport=`<details class="folder-import"><summary>Markdown 与图片一起导入</summary><form id="upload-folder"><label for="folder">选择包含文档和图片的共同上级文件夹</label><input id="folder" type="file" webkitdirectory directory multiple required><p class="hint">仅上传所选 Markdown 和它引用的图片；如果引用目录外的图片，请选择更上级文件夹。</p><label for="folder-document">选择 Markdown 文档</label><select id="folder-document" required disabled><option value="">请先选择文件夹</option></select><button type="submit" class="button" disabled>导入并创建评审</button><p id="folder-error" class="import-error" role="status" aria-live="polite"></p></form></details>`;
  const localImport=`<div class="import-primary"><button class="button" id="pick-local" type="button">选择本机文件</button><p class="hint">Markdown 引用的本地图片会自动一起导入。</p><p id="pick-error" class="import-error" role="alert"></p></div><details class="import-path"><summary>或输入文件路径</summary><form id="import-local" class="import-local"><label class="file-label" for="local-path">本机文件绝对路径</label><p class="hint" id="local-help">粘贴这台电脑上的文件绝对路径。</p><div class="import-controls"><input id="local-path" type="text" required autocomplete="off" spellcheck="false" placeholder="/home/用户名/文档/文件.md" aria-describedby="local-help import-error"><button class="button" type="submit">导入并创建评审</button></div><p id="import-error" class="import-error" role="alert"></p></form></details><details class="upload-alternative"><summary>或通过浏览器上传文件</summary>${uploadForm}</details>`;
  main.innerHTML=`<div class="page"><div class="intro"><h1>让反馈回到<br>内容之中。</h1><p>上传作品，分享链接。选中文字、标记图片位置或视频时间点，让每条意见都有迹可循。</p></div><div id="upload" class="upload">${isLocalHost?localImport:uploadForm+folderImport}</div><div class="section-head"><h2>评审列表</h2></div><div id="list" class="empty">正在加载列表…</div></div>`;
  function imported(r){if(r.warnings?.length)try{sessionStorage.setItem('lanreview-import-warnings:'+r.id,JSON.stringify(r.warnings))}catch{}location.href='/review/'+encodeURIComponent(r.id)}
  if(isLocalHost){
    document.querySelector('#pick-local').onclick=async e=>{let b=e.currentTarget,error=document.querySelector('#pick-error');error.textContent='';b.disabled=true;b.textContent='等待选择文件…';try{let r=await api('/api/reviews/pick-local',{method:'POST'});if(!r.cancelled)imported(r)}catch(err){error.textContent=err.message+(err.status===503?' 请使用下方文件路径导入。':'');if(err.status===503)document.querySelector('.import-path').open=true}finally{b.disabled=false;b.textContent='选择本机文件'}};
    document.querySelector('#import-local').onsubmit=async e=>{e.preventDefault();let input=document.querySelector('#local-path'),error=document.querySelector('#import-error'),b=e.submitter,path=input.value.trim();if(!path)return;error.textContent='';b.disabled=true;b.textContent='正在导入…';try{let r=await api('/api/reviews/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});imported(r)}catch(err){error.textContent=err.message;b.disabled=false;b.textContent='导入并创建评审'}};
  }
  document.querySelector('#upload-file').onsubmit=async e=>{e.preventDefault();let f=document.querySelector('#file').files[0];if(!f)return;let b=e.submitter,error=document.querySelector('#upload-error');error.textContent='';b.disabled=true;b.textContent='正在上传…';let form=new FormData();form.append('file',f);try{let r=await api('/api/reviews',{method:'POST',body:form});imported(r)}catch(err){error.textContent=err.message;b.disabled=false;b.textContent='创建评审'}};
  if(!isLocalHost){
    const folder=document.querySelector('#folder'), select=document.querySelector('#folder-document'), form=document.querySelector('#upload-folder'), button=form.querySelector('button'), error=document.querySelector('#folder-error');
    let files=[],docs=[];
    folder.onchange=()=>{files=Array.from(folder.files);button.disabled=true;try{indexFolderFiles(files)}catch(err){docs=[];select.innerHTML='<option value="">请重新选择文件夹</option>';select.disabled=true;error.textContent=err.message;return}docs=files.filter(f=>/\.(md|markdown)$/i.test(f.name)&&f.webkitRelativePath);select.innerHTML=docs.length?'<option value="">请选择文档</option>'+docs.map((f,i)=>`<option value="${i}">${esc(f.webkitRelativePath)}</option>`).join(''):'<option value="">未找到 Markdown 文档</option>';select.disabled=!docs.length;error.textContent=docs.length?'':files.length?'所选文件夹没有 Markdown 文档。':''};
    select.onchange=()=>{button.disabled=select.value===''};
    form.onsubmit=async e=>{e.preventDefault();if(select.value==='')return;let doc=docs[Number(select.value)];if(!doc)return;button.disabled=true;button.textContent='正在查找引用…';error.textContent='';try{let byPath=indexFolderFiles(files);let query=new FormData();query.append('file',doc,doc.name);let parsed=await api('/api/markdown/images',{method:'POST',body:query});let folderParts=doc.webkitRelativePath.normalize('NFC').split('/').slice(0,-1),root=folderParts[0],bundle=new FormData(),used=new Set(),missing=[];bundle.append('file',doc,doc.name);for(let item of parsed.references||[]){let ref=item.reference;if(typeof ref!=='string'||!ref||used.has(ref))continue;let parts=folderParts.slice(),valid=true;for(let segment of ref.split('/')){if(!segment||segment==='.')continue;if(segment==='..'){if(parts.length<=1){valid=false;break}parts.pop()}else parts.push(segment.normalize('NFC'))}if(!valid||parts[0]!==root){missing.push(item.raw);continue}let file=byPath.get(parts.join('/'));if(!file){missing.push(item.raw);continue}used.add(ref);bundle.append('references',ref);bundle.append('attachments',file,file.name)}button.textContent='正在上传…';let result=await api('/api/reviews/bundle',{method:'POST',body:bundle});imported(result)}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='导入并创建评审'}};
  }
  try{let data=await api('/api/reviews');let list=document.querySelector('#list');list.className='';list.innerHTML=data.reviews.length?`<ul class="reviews">${data.reviews.map(r=>`<li class="review-row"><span class="type">${esc(r.type).toUpperCase()}</span><a href="/review/${encodeURIComponent(r.id)}">${esc(r.name)}</a><time class="muted">${date(r.created_at)}</time></li>`).join('')}</ul>`:'<div class="empty">还没有评审。选择一个文件开始。</div>'}catch(e){document.querySelector('#list').innerHTML=`<div class="notice">${esc(e.message)}</div>`}
}
function commentHTML(c,children=[]){return `<article class="comment" id="comment-${esc(c.id)}"><div class="comment-meta"><strong>${esc(c.author)}</strong><span class="comment-meta-actions"><time>${date(c.created_at)}</time>${c.can_delete&&!c.deleted?`<button type="button" class="delete-comment" data-delete="${esc(c.id)}" aria-label="删除我的评论" title="删除我的评论" ${deletingComments.has(c.id)?'disabled':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7m4 4v5m4-5v5"/></svg></button>`:''}</span></div>${c.anchor?`<div class="comment-context">定位评论</div>`:`<div class="comment-context">${c.parent_id?'回复':'全文评论'}</div>`}${c.deleted?'':`<p>${esc(c.body)}</p>`}${!c.deleted&&typeof c.thumbnail_url==='string'&&c.thumbnail_url.startsWith('/')&&!c.thumbnail_url.startsWith('//')?visualPreview(c.thumbnail_url,c.anchor,'评论关联的画面'):''}${c.anchor?`<button class="anchor" data-anchor="${esc(c.id)}">${esc(label(c.anchor).slice(0,100))}</button>`:''} ${!c.parent_id&&!c.deleted?`<button class="anchor" data-reply="${esc(c.id)}">回复</button>`:''}${children.length?`<div style="margin-left:18px">${children.map(x=>commentHTML(x)).join('')}</div>`:''}</article>`}
function renderComments(){let cs=review.comments||[], root=cs.filter(c=>!c.parent_id);side('#count').textContent=cs.length+' 条';main.querySelector('#mobile-count').textContent=cs.length+' 条';side('#comments').innerHTML=root.length?root.map(c=>commentHTML(c,cs.filter(x=>x.parent_id===c.id))).join(''):'<div class="empty">还没有评论。选中内容，或直接留下第一条意见。</div>';main.querySelector(':scope > .workspace > aside').querySelectorAll('[data-anchor]').forEach(b=>b.onclick=()=>viewCommentAnchor(cs.find(c=>String(c.id)===b.dataset.anchor)?.anchor));main.querySelector(':scope > .workspace > aside').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteComment(cs.find(c=>String(c.id)===b.dataset.delete),b));main.querySelector(':scope > .workspace > aside').querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{if(submitting){flash('评论正在发表，请稍候');return}if(side('#body')?.value.trim()&&replying!==b.dataset.reply){flash('当前评论草稿已保留；清空草稿后可切换回复');return}replying=b.dataset.reply;if(pending){pending=null;clearTextAffordance();clearVisual('draft');side('#selected').innerHTML='';flash('回复沿用原评论的定位')}let c=cs.find(x=>String(x.id)===replying);side('#replying').innerHTML=`<div class="selected">回复 ${esc(c.author)}（沿用原评论定位） <button type="button" id="cancel-reply">取消</button></div>`;side('#cancel-reply').onclick=clearReply;saveDraft();side('#body').focus()})}
async function deleteComment(c,button){if(!c||c.deleted||!c.can_delete||deletingComments.has(c.id))return;if(!confirm('删除这条评论？已有回复会保留。'))return;deletingComments.add(c.id);button.disabled=true;commentVersion++;try{await api(`/api/reviews/${encodeURIComponent(review.id)}/comments/${encodeURIComponent(c.id)}/delete`,{method:'POST'});let current=review.comments.find(x=>x.id===c.id);if(current){current.deleted=true;current.can_delete=false;current.author='评论已删除';current.body=''}commentVersion++;renderComments();flash('评论已删除')}catch(err){flash(err.message);button.disabled=false}finally{deletingComments.delete(c.id)}}
function clearReply(){if(submitting)return;if(replying&&side('#body')?.value.trim()&&!confirm('取消回复后，这条草稿将作为新评论发表。确定取消回复吗？'))return;replying=null;side('#replying').innerHTML='';saveDraft()}
// All positions are relative to the rendered media pixels, excluding letterboxing.
let mediaAnnotation=null, visualSeekSequence=0;
function captureMediaThumbnail(){let m=main.querySelector('video, .media-wrap img');if(!m)return '';let w=m.videoWidth||m.naturalWidth,h=m.videoHeight||m.naturalHeight;if(!w||!h)return '';try{let c=document.createElement('canvas');let scale=Math.min(1,320/w,320/h);c.width=Math.max(1,Math.round(w*scale));c.height=Math.max(1,Math.round(h*scale));c.getContext('2d').drawImage(m,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.75)}catch{return ''}}
function polygonPoints(r){if(r?.type!=='polygon'||!Array.isArray(r.points)||r.points.length<3||r.points.length>256||!r.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(n=>Number.isFinite(n)&&n>=0&&n<=1)))return '';return r.points.map(p=>`${p[0]*100},${p[1]*100}`).join(' ')}
function polygonMarkup(r,mode){let points=polygonPoints(r);return points?`<svg class="media-mark polygon ${esc(mode)}" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polygon points="${points}" vector-effect="non-scaling-stroke"></polygon></svg>`:''}
